% 模拟退火参数
T_max = 1000;  T_min = 1e-4;  alpha = 0.99;
% 决策变量: [无人机速度, 飞行方向, 投放延迟, 引信时间]
lb = [70, 0, 0.001, 0.001];
ub = [140, 2*pi, 30, 30];

Temp = T_max;
while Temp > T_min
    for i = 1:iter_L
        % 对随机维度施加正态扰动生成邻域新解
        dim = randi(4);
        perturbation = (ub(dim)-lb(dim)) * (rand-0.5) * (Temp/T_max);
        new_X(dim) = current_X(dim) + perturbation;
        new_X(dim) = max(lb(dim), min(ub(dim), new_X(dim)));

        % 调用仿真模型计算新解的遮蔽时长
        new_T = calculate_total_time(new_X);
        delta_E = (-new_T) - (-current_T);

        % Metropolis准则：优解直接接受，劣解以概率接受
        if delta_E < 0
            current_X = new_X;  current_T = new_T;
        elseif rand() < exp(-delta_E / Temp)
            current_X = new_X;  current_T = new_T;
        end
    end
    Temp = Temp * alpha;  % 降温
end

pop_size = 200;  max_gen = 3000;  elite_num = 10;

for gen = 1:max_gen
    % 并行计算种群适应度
    parfor i = 1:pop_size
        fitness(i) = obj(pop(i,:), params);
    end

    % 停滞检测 -> 触发灾变重启
    if stag_cnt >= 50
        sorted_pop = pop(sorted_idx, :);
        elites = sorted_pop(1:elite_num, :);
        new_blood = lb + (ub-lb) .* rand(pop_size-elite_num, 8);
        pop = [elites; new_blood];
        continue;
    end

    % 精英保留 + 锦标赛选择 + BLX-α交叉 + 自适应变异
    next_pop(1:elite_num, :) = sorted_pop(1:elite_num, :);
    for i = (elite_num+1):pop_size
        p1 = sorted_pop(tour_select(pop_size), :);
        p2 = sorted_pop(tour_select(pop_size), :);
        child = crossover_blend(p1, p2);
        mut_scale = 1 - (gen/max_gen)^2;
        child = mutate(child, lb, ub, mut_scale);
        next_pop(i, :) = repair(child, lb, ub);
    end
end

% 自适应量子旋转门：根据适应度差距动态调整旋转角度
function delta_theta = get_rotation_params(current_fitness, ...
        global_best_fitness, current_binary, global_best_binary)
    s = zeros(1, n_genes);
    diff_indices = find(current_binary ~= global_best_binary);
    s(diff_indices(current_binary(diff_indices)==0)) = 1;
    s(diff_indices(current_binary(diff_indices)==1)) = -1;

    % 适应度差距越大 -> 旋转角越大（大步探索）
    f_diff = abs(current_fitness - global_best_fitness);
    f_norm = min(f_diff / max_possible_diff, 1);
    adaptive_magnitude = theta_min + (theta_max-theta_min) * f_norm;
    delta_theta = s * adaptive_magnitude;
end

% 对量子染色体施加旋转门
for j = 1:n_genes
    angle = delta_theta(j);
    R = [cos(angle), -sin(angle); sin(angle), cos(angle)];
    q_chromosome(:,j) = R * q_chromosome(:,j);
end

